function getAdviceSet(group, idx){
  const entry = branchAdvice[currentGuideId]?.[group]?.[idx];
  if(!entry) return null;
  return entry[["ja","en","zh","vi","ko"].indexOf(currentLang)] || entry[0];
}

function showGasEmergency(){
 const copy={
 ja:{title:"今すぐ安全を確保してください",items:["火を使わない。コンロの点火・たばこ・ライターも禁止。","換気扇・照明・家電などの電気スイッチに触れない。ONだけでなくOFFもしない。","窓や戸を手で開ける。換気扇は使わない。","安全にできる場合だけガス栓を閉める。危険なら操作せず避難する。","屋外の安全な場所へ移動し、ガス会社の緊急窓口へ連絡する。電話番号は請求書や公式サイトで確認する。"],note:"火災・けが・差し迫った危険がある場合は119（消防・救急）または110（警察）へ。ガス臭い場所に戻らないでください。",src:"経済産業省：ガス臭いと感じた時の対応",extra:"日本ガス協会：ガス臭いと感じたら"},
 en:{title:"Move to safety now",items:["Do not use flames, ignite the stove, smoke or use a lighter.","Do not touch electrical switches or appliances, including turning them ON or OFF.","Open doors and windows by hand. Do not use an exhaust fan.","Close the gas valve only if safe. Do not delay evacuation.","Move outdoors to a safe place and call your gas supplier's emergency line. Find the number on your bill or its official website."],note:"For fire, injury or immediate danger in Japan, call 119 (fire/ambulance) or 110 (police). Do not re-enter.",src:"METI: What to do if you smell gas",extra:"Japan Gas Association: If you smell gas"},
 zh:{title:"请立即转移到安全地点",items:["禁止使用明火、点火、吸烟或使用打火机。","不要触碰电灯、排气扇或家电开关；不要开，也不要关。","用手打开门窗。不要使用排气扇。","只有在确保安全时才关闭燃气阀；不要因此延误撤离。","前往室外安全地点，联系燃气供应商的紧急窗口。电话请查看账单或官网。"],note:"在日本如发生火灾、受伤或紧急危险，请拨打119（消防/急救）或110（警察）。不要返回现场。",src:"日本经济产业省：闻到燃气味时的应对方法",extra:"日本燃气协会：闻到燃气味时"},
 vi:{title:"Hãy đến nơi an toàn ngay lập tức",items:["Không dùng lửa, bật bếp, hút thuốc hoặc dùng bật lửa.","Không chạm vào công tắc hoặc thiết bị điện, kể cả bật hay tắt.","Mở cửa sổ và cửa ra vào bằng tay. Không dùng quạt thông gió.","Chỉ khóa van gas nếu an toàn. Không trì hoãn sơ tán.","Di chuyển ra ngoài và gọi đường dây khẩn cấp của nhà cung cấp gas. Tìm số trên hóa đơn hoặc trang web chính thức."],note:"Nếu có cháy, bị thương hoặc nguy hiểm tức thời tại Nhật Bản, gọi 119 (cứu hỏa/cấp cứu) hoặc 110 (cảnh sát). Không quay lại.",src:"METI: Cách xử lý khi ngửi thấy mùi gas",extra:"Hiệp hội Gas Nhật Bản: Khi ngửi thấy mùi gas"},
 ko:{title:"즉시 안전한 장소로 이동하세요",items:["불을 사용하지 마세요. 레인지 점화, 흡연, 라이터 사용도 금지합니다.","환풍기·조명·가전제품의 전기 스위치를 만지지 마세요. 켜거나 끄는 것 모두 금지합니다.","창문과 문을 손으로 여세요. 환풍기는 사용하지 마세요.","안전할 때만 가스 밸브를 잠그세요. 위험하면 조작하지 말고 대피하세요.","실외 안전한 장소로 이동해 가스 공급사의 긴급 연락처로 연락하세요. 번호는 청구서나 공식 웹사이트에서 확인하세요."],note:"일본에서 화재·부상·급박한 위험이 있으면 119(소방·구급) 또는 110(경찰)에 연락하세요. 현장으로 돌아가지 마세요.",src:"일본 경제산업성: 가스 냄새가 날 때의 대응",extra:"일본가스협회: 가스 냄새가 날 때"}
 };
 const c=copy[currentLang]||copy.ja, card=$("#resultCard");
 $("#questionCard").hidden=true; card.hidden=false;
 card.innerHTML='<p class="step-label">SAFETY FIRST</p><h3>'+c.title+'</h3><ol>'+c.items.map(x=>'<li>'+x+'</li>').join("")+'</ol><p><strong>'+c.note+'</strong></p><p><a href="https://www.meti.go.jp/policy/safety_security/industrial_safety/sangyo/citygas/anzen_torikumi/file_jisyuhoan/study/fireaccident/gas_smell.html" target="_blank" rel="noopener noreferrer">'+c.src+' ↗</a></p><p><a href="https://www.gas.or.jp/anzen/gas-smell/" target="_blank" rel="noopener noreferrer">'+c.extra+' ↗</a></p><div class="result-actions"><button class="small-action" id="backToCategories">'+tr("back")+'</button></div>';
 $("#backToCategories").onclick=closeGuide;
}

function openGuide(id){
  const guide=guides[id]; if(!guide) return;
  currentGuide=guide; currentGuideId=id; currentStep=0; selectedAnswers=[];
  $("#guideTitle").textContent=guide.title[currentLang]||guide.title.ja;
  $("#guideIntro").textContent=guide.intro[currentLang]||guide.intro.ja;
  $("#guidePanel").hidden=false; $("#questionCard").hidden=false; $("#resultCard").hidden=true;
  if(id==="gasleak"){showGasEmergency();}else{renderQuestion();}
  $("#guidePanel").scrollIntoView({behavior:"smooth",block:"start"});
}
function renderQuestion(){
  const q=currentGuide.questions[currentStep];
  $("#stepLabel").textContent=`${tr("step")} ${currentStep+1} / ${currentGuide.questions.length}`;
  $("#questionTitle").textContent=q.q[currentLang]||q.q.ja;
  const box=$("#answerOptions"); box.innerHTML="";
  q.a.forEach((answer,index)=>{
    const b=document.createElement("button"); b.className="answer-option";
    b.textContent=answer.t[currentLang]||answer.t.ja;
    b.addEventListener("click",()=>{
      selectedAnswers[currentStep]=index;
      if(currentGuideId==="gasstove" && currentStep===0 && index===0){openGuide("gasleak");return;}
      if(currentStep<currentGuide.questions.length-1){currentStep++;renderQuestion();}
      else showResult();
    });
    box.appendChild(b);
  });
}
function showResult(){
  const r=currentGuide.result, card=$("#resultCard");
  const lang=currentLang;
  const advice1=getAdviceSet("q1",selectedAnswers[0]);
  const advice2=getAdviceSet("q2",selectedAnswers[1]);
  const selected=currentGuide.questions.map((q,i)=>`<li><b>${q.q[lang]||q.q.ja}</b><br>${q.a[selectedAnswers[i]].t[lang]||q.a[selectedAnswers[i]].t.ja}</li>`).join("");
  const tailored=[advice1,advice2].filter(Boolean).map((t,i)=>`<li>${t}</li>`).join("");
  $("#questionCard").hidden=true; card.hidden=false;
  card.innerHTML=`
    <p class="step-label">${tr("result")}</p>
    <h3>${currentGuide.title[lang]||currentGuide.title.ja}</h3>
    <h4>${tr("yourAnswers")}</h4>
    <ul>${selected}</ul>
    <h4>${tr("priorityActions")}</h4>
    <ul>${tailored}</ul>
    <h4>${tr("first")}</h4><p>${r.first[lang]||r.first.ja}</p>
    <h4>${tr("steps")}</h4><ul>${(r.steps[lang]||r.steps.ja).map(x=>`<li>${x}</li>`).join("")}</ul>
    <h4>${tr("documents")}</h4><p>${r.docs[lang]||r.docs.ja}</p>
    <h4>${tr("caution")}</h4><p>${r.caution[lang]||r.caution.ja}</p>
    <p><a href="${r.source}" target="_blank" rel="noopener noreferrer">${(r.sourceLabel[lang]||r.sourceLabel.ja)} ↗</a></p>
    <div class="result-actions"><button class="small-action" id="restartButton">${tr("restart")}</button><button class="small-action" id="backToCategories">${tr("back")}</button></div>`;
  $("#restartButton").onclick=()=>{currentStep=0;selectedAnswers=[];card.hidden=true;$("#questionCard").hidden=false;renderQuestion();};
  $("#backToCategories").onclick=closeGuide;
}
function closeGuide(){
  $("#guidePanel").hidden=true; $("#categories").scrollIntoView({behavior:"smooth"});
  currentGuide=null; currentGuideId=null; selectedAnswers=[];
}
document.querySelectorAll(".category-card").forEach(btn=>btn.addEventListener("click",()=>{
  const category=btn.dataset.category;
  document.querySelectorAll(".popular-item").forEach(item=>{
    item.hidden=item.dataset.topicCategory!==category;
  });
  document.querySelector(".popular").scrollIntoView({behavior:"smooth",block:"start"});
}));
$("#showAllTopics").addEventListener("click",()=>{
  document.querySelectorAll(".popular-item").forEach(item=>{item.hidden=false;});
});
document.querySelectorAll("[data-quick]").forEach(btn=>btn.addEventListener("click",()=>openGuide(btn.dataset.quick)));
$("#languageSelect").addEventListener("change",e=>{
  currentLang=e.target.value; localize();
  if(currentGuide){
    $("#guideTitle").textContent=currentGuide.title[currentLang]||currentGuide.title.ja;
    $("#guideIntro").textContent=currentGuide.intro[currentLang]||currentGuide.intro.ja;
    if(currentGuideId==="gasleak") showGasEmergency();
    else if($("#resultCard").hidden) renderQuestion(); else showResult();
  }
});
$("#backButton").addEventListener("click",closeGuide);
$("#homeLink").addEventListener("click",e=>{e.preventDefault();closeGuide();window.scrollTo({top:0,behavior:"smooth"});});
localize();
